import { readFileSync, writeFileSync } from 'node:fs';
const R = p => JSON.parse(readFileSync(p, 'utf8'));
const base = R('/workspace/probe/cases/array-keywords.json');
const s2 = R('/workspace/probe/cases/scratch2.json');
const s3 = R('/workspace/probe/cases/scratch3.json');
const s4 = R('/workspace/probe/cases/scratch4.json');

// indices of base cases to KEEP
const keep = [0,1,2,3,5,8,15,18,19,20,21,22,25,26,27,29,31,32,36,38,39,
 41,43,45,46,49,50,52,54,58,59,60,61,65,68,70,72,
 73,74,75,78,83,86,87,88,89,91,92,93,
 94,95,97,98,101,102,103,107,112,113,116,
 117,119,120,123,124,126,127,129,130,
 131,133,134,135,136,139,140,141,142,143,145,146,147,148,149,150];
const byNote = (arr, prefixes) => prefixes.map(p => {
  const hit = arr.find(c => c.note.split(' ')[0] === p);
  if (!hit) throw new Error('missing ' + p);
  return hit;
});
const out = [
  ...keep.map(i => base[i]),
  ...byNote(s2, ['A','B','C','D','E','F','G','AU','H','AX1','M','O','S','AG','Z','AB','AF','AK','X','Y']),
  ...byNote(s3, ['P1','P2','P5','P6','P7','P8','P9','P10','P12','P13','P18']),
  ...byNote(s4, ['R1','R2','R3','R6']),
];
// rewrite the scratch notes into descriptive prose
const notes = {
 A:'additionalItems: non-array instance returns BEFORE len(items), so items:true raises nothing => 0',
 B:'additionalItems as schema is ignored when items is absent (default {} is an object) => 0',
 C:'additionalItems schema with 2 failing keywords x 2 extras => 4',
 D:'additionalItems subschema is lazy: bad maxItems never compared (extra is a string) => 0',
 E:'EXCEPTION: bad subschema inside additionalItems IS reached for an array extra',
 F:'tuple longer than instance + additionalItems schema: no extras => 0',
 G:'tuple longer than instance + additionalItems:false: only tuple errors => 2',
 AU:'nested: tuple slot yields 2, additionalItems extra yields 1 => 3',
 H:'maxItems inside items: one error per failing element => 2',
 AX1:'maxItems:NaN => len>NaN is False => 0 errors (never fails)',
 M:'uniqueItems: object KEY ORDER is irrelevant, {a,b} == {b,a} => 1',
 O:'uniqueItems: unbool is applied recursively, [true] != [1] => 0',
 S:'uniqueItems: a single NaN is fine => 0',
 AG:'items schema vs 6 heterogeneous elements: only the string passes => 5',
 Z:'contains + minItems on empty array => 2',
 AB:'nested additionalItems:false: one aggregate error per nested array => 2',
 AF:'recursive $ref through items: innermost non-array => 1',
 AK:'items subschema with only array keywords: non-array elements silently pass => 1',
 X:'items(3)+uniqueItems(1)+maxItems(1)+minItems(1)+contains(1), additionalItems ignored => 7',
 Y:'tuple(2)+additionalItems:false(1)+uniqueItems(1)+minItems(1)+contains(1)+maxItems(1) => 7',
 P1:'uniqueItems: 2^53+1 and 2^53 are DISTINCT ints in Python (JS doubles collide) => 0',
 P2:'const 2^53 vs instance 2^53+1: distinct in Python (JS doubles collide) => 1',
 P5:'no cap on error count: 40 elements vs items:false => 40',
 P6:'additionalItems:false with 20 extras is still exactly 1 error',
 P7:'tuple [true,false,{type:string}] vs [1,2,3] => 2',
 P8:'3 array keywords inside items x 2 failing elements => 6',
 P9:'tuple + additionalItems:false on empty array => 0',
 P10:'items only descends one level: [[["x"]]] vs items.type=string => 1',
 P12:'4 levels of nested items => 2 leaf errors, not collapsed',
 P13:'nested sums: (items 1 + minItems 0 + contains 1) + (1+1+1) => 5',
 P18:'allOf inside items: 2 failing branches x 2 elements => 4',
 R1:'$ref REPLACES sibling keywords in draft7: items:false ignored => 0',
 R2:'$ref sibling override: only the $ref target maxItems fires => 1',
 R3:'$ref inside an items subschema also suppresses its sibling type => 1',
 R6:'minItems:true == 1 vs empty array => 1',
};
for (const c of out) {
  const k = c.note.split(' ')[0];
  if (notes[k]) c.note = notes[k];
}
// fix stale/uncertain notes on base cases
const fix = {
 '[NaN,NaN]':'uniqueItems: json.loads NaN literals are the SAME object, so NaN==NaN here => 1',
};
for (const c of out) if (fix[c.a] && c.b === '{"uniqueItems":true}') c.note = fix[c.a];
writeFileSync('/workspace/probe/cases/array-keywords.json', JSON.stringify(out, null, 1));
console.log('final case count', out.length);

